<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\UserProfilePhoneNumberVO;

trait UserProfilePhoneNumberAccessor
{
    private ?UserProfilePhoneNumberVO $_phoneNumber = null;
    public function getPhoneNumber(): ?string
    {
        return $this->_phoneNumber?->value();
    }
    public function phoneNumber(): ?UserProfilePhoneNumberVO
    {
        return $this->_phoneNumber;
    }
    public function isPhoneNumberChanged(?self $original = null): bool
    {
        return null !== $this->_phoneNumber && !$this->_phoneNumber->equals($original?->_phoneNumber);
    }
    public function withPhoneNumber(UserProfilePhoneNumberVO|string|null $phoneNumber): self
    {
        $copy = clone $this;
        $copy->_phoneNumber = UserProfilePhoneNumberVO::from($phoneNumber);
        return $copy;
    }
}
